      emit_indent(g_pre, g_indent);
      emit_ctype(c, kt, g_pre);
      buf_printf(g_pre, " _t%d = (", tkv);
      emit_ctype(c, kt, g_pre);
      buf_printf(g_pre, ")sp_poly_as_handle(%s, %s, \"%s\");\n",
                 krb.p ? krb.p : "sp_box_nil()", ty_nullable_builtin_id(kt), knm);
      free(krb.p);
